"""Evidence-backed findings.

* Deterministic findings are generated by code directly from graph records (origin=graph or
  deterministic_analysis) and always carry references.
* Model claims are accepted only if every cited id exists in the investigation context AND every
  entity-like id mentioned in the statement was actually retrieved. Anything else is recorded as an
  unsupported claim and excluded from the findings.
"""

from __future__ import annotations

import re

from app.agents.context import InvestigationContext
from app.agents.llm.base import FinishPayload
from app.agents.safety import injection_signals, sanitize_text
from app.policies.engine import ProposedAction
from app.schemas.common import Ref
from app.schemas.graph import GraphPayload, Truncation
from app.schemas.investigation import Finding, UnsupportedClaim
from app.schemas.risk import RiskAssessment

_ID_TOKEN = re.compile(
    r"\b(ALT-\d{3,6}|EV-\d{3,6}|INC-\d{4}-\d{3}|inc-\d{4}-\d{3}|(?:ip|dev|svc|idn|vuln|ioc|per|team)-[a-z0-9][a-z0-9-]*"
    r"|path-[0-9a-f]{12}|tc-\d{2})\b"
)
MAX_GRAPH_NODES = 150


def _ref_type(ctx: InvestigationContext, rid: str) -> str:
    if rid in ctx.paths:
        return "path"
    if rid in ctx.evidence:
        return "evidence"
    if rid in ctx.edges:
        return "edge"
    if any(t.id == rid for t in ctx.tool_calls):
        return "tool_call"
    return "node"


def validate_claims(
    finish: FinishPayload | None, ctx: InvestigationContext
) -> tuple[list[Finding], list[UnsupportedClaim]]:
    if finish is None:
        return [], []
    known = ctx.known_ref_ids()
    known_lower = {k.lower() for k in known}
    accepted: list[Finding] = []
    rejected: list[UnsupportedClaim] = [
        UnsupportedClaim(statement=sanitize_text(m, 600), reason="Malformed claim (did not match the claim format).")
        for m in finish.malformed_claims
    ]
    for i, claim in enumerate(finish.claims, start=1):
        statement = sanitize_text(claim.statement, 600)
        refs = [r for r in claim.refs if isinstance(r, str)]
        if not refs:
            rejected.append(UnsupportedClaim(statement=statement, reason="No references cited."))
            continue
        unknown_refs = [r for r in refs if r not in known]
        if unknown_refs:
            rejected.append(
                UnsupportedClaim(statement=statement, reason=f"Cites ids not retrieved by any tool: {unknown_refs[:5]}")
            )
            continue
        mentioned = {m.group(0) for m in _ID_TOKEN.finditer(statement)}
        unknown_mentions = [m for m in mentioned if m.lower() not in known_lower]
        if unknown_mentions:
            rejected.append(
                UnsupportedClaim(
                    statement=statement, reason=f"Mentions entities never retrieved: {unknown_mentions[:5]}"
                )
            )
            continue
        if injection_signals(statement):
            rejected.append(UnsupportedClaim(statement=statement, reason="Claim text echoes injected instructions."))
            continue
        accepted.append(
            Finding(
                id=f"F-M{i:02d}",
                kind=claim.kind,
                statement=statement,
                origin="model",
                refs=[Ref(type=_ref_type(ctx, r), id=r) for r in refs],
            )
        )
    return accepted, rejected


def deterministic_findings(ctx: InvestigationContext, risk: RiskAssessment | None) -> list[Finding]:
    out: list[Finding] = []

    def add(kind: str, statement: str, refs: list[Ref], origin: str = "graph", conf: float | None = None) -> None:
        out.append(
            Finding(
                id=f"F-{len(out) + 1:02d}",
                kind=kind,
                statement=statement,
                refs=refs,
                origin=origin,
                confidence=conf,
            )
        )

    if ctx.target is None:
        add(
            "observed_fact",
            f"Target {ctx.target_id} does not exist in the graph.",
            [Ref(type="node", id=ctx.target_id)],
        )
        return out
    for edge, node in ctx.triggering:
        add(
            "observed_fact",
            f"{node.label} {node.display_name} triggered {ctx.target_id} "
            f"(role: {edge.properties.get('role', 'unspecified')}).",
            [Ref(type="edge", id=edge.id)],
        )
    for e in ctx.edges.values():
        if e.temporal_status == "historical":
            add(
                "observed_fact",
                f"Historical relationship {e.source} -[{e.type}]-> {e.target} ended {e.properties.get('valid_to')}; "
                "it is shown for context and not treated as current.",
                [Ref(type="edge", id=e.id)],
            )
    for ev in sorted(ctx.evidence.values(), key=lambda x: x.id):
        verb = "supports" if ev.stance == "supports" else "contradicts"
        if ev.excluded_from_scoring:
            add(
                "observed_fact",
                f"{ev.id} ({ev.source_system}) contains text resembling instructions to an AI "
                f"agent ({', '.join(ev.injection_signals)}); treated as untrusted and excluded.",
                [Ref(type="evidence", id=ev.id)],
            )
            continue
        add(
            "observed_fact",
            f"{ev.id} [{ev.source_system} {ev.source_ref}, {ev.observed_at}] {verb} on {ev.target_id}: {ev.claim}",
            [Ref(type="evidence", id=ev.id)],
            conf=ev.confidence,
        )
    for p in top_paths(ctx, 3):
        add(
            "inference",
            f"{p.hops}-hop path: {p.description}",
            [Ref(type="path", id=p.id)],
            origin="deterministic_analysis",
        )
    for link in sorted(ctx.incidents.values(), key=lambda x: x.hops):
        add(
            "observed_fact",
            f"Historical incident {link.incident.id} ({link.incident.display_name}, opened "
            f"{link.opened_at}) is linked by a {link.link} {link.hops}-hop chain.",
            [Ref(type="node", id=link.incident.id), Ref(type="path", id=link.path_id)],
        )
    crit = [
        a
        for a in ctx.impacted.values()
        if a.node.properties.get("criticality") in ("high", "critical") and a.relation != "upstream_dependent"
    ]
    for a in sorted(crit, key=lambda x: x.hops)[:4]:
        refs = [Ref(type="node", id=a.node.id)] + ([Ref(type="path", id=a.path_id)] if a.path_id else [])
        add(
            "inference",
            f"{a.node.label} {a.node.display_name} ({a.node.properties.get('criticality')}) is in the "
            f"blast radius as {a.relation.replace('_', ' ')} ({a.hops} hop(s)).",
            refs,
            origin="deterministic_analysis",
        )
    for v in ctx.vulnerabilities.values():
        if v.status == "open":
            add(
                "observed_fact",
                f"{v.vulnerability.id} (CVSS {v.vulnerability.properties.get('cvss')}) is open on {v.asset_id}.",
                [Ref(type="edge", id=v.edge_id)],
            )
    comps = ctx.analytics.get("components") or {}
    info = comps.get(ctx.target_id)
    if info and info.get("found") and not info.get("critical_or_high_assets"):
        add(
            "observed_fact",
            f"{ctx.target_id} lies in a connected component of {info['component_size']} entities "
            "with no high/critical assets (FalkorDB algo.WCC).",
            [Ref(type="calculation", id="algo.WCC")],
            origin="deterministic_analysis",
        )
    for prior in ctx.prior_investigations[:3]:
        add(
            "observed_fact",
            f"Prior investigation {prior['investigation_id']} ({prior.get('verdict')}, risk "
            f"{prior.get('risk_score')}) involved {', '.join(prior['shared_entities'][:5])}.",
            [Ref(type="tool_call", id=_last_call(ctx, "get_prior_investigations"))],
        )
    if risk is not None:
        add(
            "hypothesis",
            f"Assessment: {risk.verdict.replace('_', ' ')} — {risk.verdict_reason}",
            [Ref(type="calculation", id="risk")],
            origin="deterministic_analysis",
            conf=risk.confidence,
        )
    return out


def _last_call(ctx: InvestigationContext, tool: str) -> str:
    for t in reversed(ctx.tool_calls):
        if t.tool == tool:
            return t.id
    return "none"


def top_paths(ctx: InvestigationContext, n: int) -> list:  # type: ignore[type-arg]
    """Most informative current paths: those ending at incidents/vulns/high-value assets, longest first."""
    candidates = [
        p
        for pid, p in ctx.paths.items()
        if ctx.path_kinds.get(pid) in ("attack_path", "incident_link", "shortest_path") and not p.contains_historical
    ]

    open_vulns = {v.vulnerability.id for v in ctx.vulnerabilities.values() if v.status == "open"}

    def score(p) -> tuple[int, int, int]:  # type: ignore[no-untyped-def]
        end = ctx.nodes.get(p.end_id)
        crit = end.properties.get("criticality") if end else None
        if p.end_label == "Incident" or p.end_id in open_vulns:
            value = 3
        elif crit in ("critical", "high"):
            value = 2
        elif p.end_label == "Vulnerability":  # remediated / unknown status: low informational value
            value = 0
        else:
            value = 1
        # Prefer chains that traverse real assets (attack propagation) over indicator-only links.
        assets = sum(1 for nid in p.node_ids[1:-1] if (n := ctx.nodes.get(nid)) and n.label in ("Device", "Service"))
        return value, assets, p.hops

    chosen, seen_ends = [], set()
    for p in sorted(candidates, key=score, reverse=True):
        if p.end_id in seen_ends:
            continue
        seen_ends.add(p.end_id)
        chosen.append(p)
        if len(chosen) >= n:
            break
    return chosen


def build_graph_payload(ctx: InvestigationContext) -> GraphPayload:
    highlighted = [p.id for p in top_paths(ctx, 5)]
    priority: list[str] = [ctx.target_id]
    for pid in highlighted:
        priority += ctx.paths[pid].node_ids
    priority += [n.id for _, n in ctx.triggering] + list(ctx.impacted) + list(ctx.evidence)
    for p in ctx.paths.values():
        priority += p.node_ids
    priority += list(ctx.nodes)
    ordered: list[str] = []
    for nid in priority:
        if nid in ctx.nodes and nid not in ordered:
            ordered.append(nid)
    keep = set(ordered[:MAX_GRAPH_NODES])
    nodes = [ctx.nodes[i] for i in ordered[:MAX_GRAPH_NODES]]
    edges = [e for e in ctx.edges.values() if e.source in keep and e.target in keep]
    paths = [p for p in ctx.paths.values() if set(p.node_ids) <= keep]
    truncated = len(ordered) > MAX_GRAPH_NODES or ctx.truncated
    return GraphPayload(
        nodes=nodes,
        edges=edges,
        paths=paths,
        highlighted_path_ids=[h for h in highlighted if h in {p.id for p in paths}],
        evidence_refs=sorted(ctx.evidence),
        truncation=Truncation(
            truncated=truncated,
            max_nodes=MAX_GRAPH_NODES,
            max_depth=ctx.max_depth,
            reason="node cap or traversal limit reached" if truncated else None,
        ),
    )


def deterministic_narrative(
    ctx: InvestigationContext, risk: RiskAssessment | None, actions: list[ProposedAction]
) -> str:
    if ctx.target is None:
        return f"{ctx.target_id} was not found in the security graph. No conclusion is possible."
    t = ctx.target
    parts = [
        f"{t.id} — {t.display_name} (severity {t.properties.get('severity', 'n/a')}, "
        f"status {t.properties.get('status', 'n/a')})."
    ]
    trig = [f"{n.label} {n.display_name} ({e.properties.get('role')})" for e, n in ctx.triggering]
    if trig:
        parts.append("Triggered by " + ", ".join(trig) + ".")
    paths = top_paths(ctx, 2)
    if paths:
        parts.append("Graph chain: " + " | ".join(f"[{p.hops} hops] {p.description}" for p in paths) + ".")
    else:
        parts.append("No propagation path to assets, vulnerabilities or incidents was found within the hop limit.")
    if ctx.incidents:
        parts.append(
            "Linked incidents: "
            + ", ".join(f"{i.incident.id} ({i.link}, {i.hops} hops)" for i in ctx.incidents.values())
            + "."
        )
    crit = sorted(
        (
            a
            for a in ctx.impacted.values()
            if a.relation != "upstream_dependent" and a.node.properties.get("criticality") in ("high", "critical")
        ),
        key=lambda a: a.hops,
    )
    if crit:
        parts.append(
            "Blast radius includes "
            + ", ".join(
                f"{a.node.display_name} ({a.node.properties.get('criticality')}, {a.relation.replace('_', ' ')})"
                for a in crit[:4]
            )
            + "."
        )
    con = [e for e in ctx.evidence.values() if e.stance == "contradicts" and not e.excluded_from_scoring]
    if con:
        parts.append("Contradicting evidence: " + "; ".join(f"{e.id} ({e.claim})" for e in con) + ".")
    flagged = [e.id for e in ctx.evidence.values() if e.excluded_from_scoring]
    if flagged:
        parts.append(f"Ignored as suspected prompt injection: {', '.join(flagged)}.")
    if risk:
        parts.append(
            f"Deterministic risk {risk.score}/100 ({risk.band}); verdict {risk.verdict.replace('_', ' ')}; "
            f"confidence {risk.confidence_band}."
        )
    if actions:
        parts.append(
            "Proposed simulated actions (require approval): "
            + ", ".join(f"{a.action_type.value} → {a.target_id}" for a in actions)
            + "."
        )
    else:
        parts.append("No response actions proposed.")
    return " ".join(parts)
